func contentGoal12() content.GoalBlock {
	var contentCodeOut io.Writer
	_ = contentCodeOut
	return func(contentCodeParent *core.Frame, contentCodeW io.Writer) content.GoalBlock {
		contentCodeOut = contentCodeW
		tensorfs.ListOutput = contentCodeW
		defer func() { tensorfs.ListOutput = nil }()
		b := contentCodeParent
		_ = b
		{
			// contentcode:block 0 content/stats.md #1

			x := tensor.Tensor(tensor.NewFloat64SpacedLinear(tensor.NewFloat64Scalar(0.), tensor.NewFloat64Scalar(12.), 12., false))
			tensorfs.Record(x, `x`)
			d := tensor.Tensor(tensor.Reshape(x, 3, 2, 2))
			tensorfs.Record(d, `d`)

			mean := tensor.Tensor(stats.Mean(x))
			tensorfs.Record(mean, `mean`)
			meand := tensor.Tensor(stats.Mean(d))
			tensorfs.Record(meand, `meand`)

			fmt.Fprintln(contentCodeOut, "x:", x)
			fmt.Fprintln(contentCodeOut, "mean:", mean)
			fmt.Fprintln(contentCodeOut, "d:", d)
			fmt.Fprintln(contentCodeOut, "mean d:", meand)

			return func(contentCodeParent *core.Frame, contentCodeW io.Writer) content.GoalBlock {
				contentCodeOut = contentCodeW
				tensorfs.ListOutput = contentCodeW
				defer func() { tensorfs.ListOutput = nil }()
				b := contentCodeParent
				_ = b
				{
					// contentcode:block 1 content/stats.md #2

					x := tensor.Tensor(tensor.NewIntFromValues([]int{1, 2, 3, 4, 5, 6, 7, 8, 9, 30}...))
					tensorfs.Record(x, `x`)

					fmt.Fprintln(contentCodeOut, "median:", stats.Median(x))
					fmt.Fprintln(contentCodeOut, "quantiles:", stats.Quantiles(x, tensor.NewFloat64FromValues(0.1, 0.9)))
					fmt.Fprintln(contentCodeOut, "box stats:", stats.BoxStats(x, 1.5))

					return func(contentCodeParent *core.Frame, contentCodeW io.Writer) content.GoalBlock {
						contentCodeOut = contentCodeW
						tensorfs.ListOutput = contentCodeW
						defer func() { tensorfs.ListOutput = nil }()
						b := contentCodeParent
						_ = b
						{
							// contentcode:block 2 content/stats.md #3
							dt := table.New().SetNumRows(4)
							dt.AddStringColumn("Name")
							dt.AddFloat32Column("Value")
							for i := range 4 {
								gp := "A"
								if i >= 2 {
									gp = "B"
								}
								dt.Column("Name").SetStringRow(gp, i, 0)
								dt.Column("Value").SetFloatRow(float64(i), i, 0)
							}
							dir, _ := tensorfs.NewDir("Group")
							stats.TableGroups(dir, dt, "Name")
							stats.TableGroupStats(dir, stats.StatMean, dt, "Value")
							gdt := stats.GroupStatsAsTableNoStatName(dir)

							fmt.Fprintln(contentCodeOut, "dt:", dt)
							fmt.Fprintln(contentCodeOut, "tensorfs listing:")
							fmt.Fprintln(contentCodeOut, dir.ListAll())

							fmt.Fprintln(contentCodeOut, "gdt:", gdt)

							return nil
						}
					}
				}
			}
		}
	}
}

